const API = '/api/v1'
type User = { email: string; name: string; role: string; wallet_address?: string; is_verified?: boolean; is_active?: boolean; phone?: string }
type AuthValue = { user: User | null; token: string | null; initializing: boolean; login: (email: string, password: string) => Promise<void>; register: (data: SignupData) => Promise<void>; updateUser: (user: User) => void; logout: () => void }
type SignupData = { name: string; email: string; phone: string; password: string }
type Appointment = { id: string; service: string; practitioner?: string; preferred_date: string; preferred_time: string; status: string; patient_name?: string; notes?: string }
type Incident = { id: string; timestamp: string; attack_type: string; severity: string; source: string; details: { score?: number; reason_codes?: string[]; suggested_action?: string }; is_simulated: boolean }
type AuditItem = { id: string; timestamp: string; actor_email?: string; action: string; resource_type: string; resource_id?: string; outcome: string }
type NotificationItem = { id: string; channel: string; status: string; payload: { kind?: string; status?: string }; created_at: string; delivered_at?: string }
type ApiError = { detail?: string | { message?: string } }

async function postAuth<T>(path: string, payload: object): Promise<T> {
  let response: Response
  try {
    response = await fetch(`${API}${path}`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(payload),
    })
  } catch {
    throw new Error('The secure server is unavailable. Start the backend, then try again.')
  }

  const data = await response.json().catch(() => ({})) as T & ApiError
  if (!response.ok) {
    const detail = typeof data.detail === 'string' ? data.detail : data.detail?.message
    throw new Error(detail || 'Unable to complete the request')
  }
  return data
}

const AuthContext = createContext<AuthValue | null>(null)
const useAuth = () => useContext(AuthContext)!

function AuthProvider({ children }: { children: ReactNode }) {
  const [token, setToken] = useState<string | null>(() => sessionStorage.getItem('healer_token'))
  const [initializing, setInitializing] = useState(true)
  const [user, setUser] = useState<User | null>(() => {
    try { return JSON.parse(sessionStorage.getItem('healer_user') || 'null') } catch { return null }
  })
  useEffect(() => {
    const storedToken = sessionStorage.getItem('healer_token')
    if (!storedToken) { setUser(null); setInitializing(false); return }
    fetch(`${API}/auth/me`, { headers: { Authorization: `Bearer ${storedToken}` } })
      .then(response => {
        if (!response.ok) throw new Error('Invalid session')
        return response.json() as Promise<User>
      })
      .then(currentUser => save(storedToken, currentUser))
      .catch(() => {
        sessionStorage.removeItem('healer_token')
        sessionStorage.removeItem('healer_user')
        setToken(null)
        setUser(null)
      })
      .finally(() => setInitializing(false))
  }, [])
  const save = (nextToken: string, nextUser: User) => {
    sessionStorage.setItem('healer_token', nextToken); sessionStorage.setItem('healer_user', JSON.stringify(nextUser))
    setToken(nextToken); setUser(nextUser)
  }
  const login = async (email: string, password: string) => {
    const data = await postAuth<{ access_token: string; user: User }>('/auth/login', { email, password })
    save(data.access_token, data.user)
  }
  const register = async (payload: SignupData) => {
    await postAuth('/auth/register', { ...payload, role: 'Patient' })
    await login(payload.email, payload.password)
  }
  const logout = () => { if(token) void fetch(`${API}/auth/logout`,{method:'POST',headers:{Authorization:`Bearer ${token}`}}); sessionStorage.removeItem('healer_token'); sessionStorage.removeItem('healer_user'); setToken(null); setUser(null) }
  const updateUser = (nextUser: User) => { sessionStorage.setItem('healer_user', JSON.stringify(nextUser)); setUser(nextUser) }
  return <AuthContext.Provider value={{ user, token, initializing, login, register, updateUser, logout }}>{children}</AuthContext.Provider>
}

