function AppointmentPage() { usePage('Book an Appointment'); const location=useLocation(); const initial=new URLSearchParams(location.search).get('service')||''; const [step,setStep]=useState(1); const [done,setDone]=useState(false); const [error,setError]=useState(''); const [submitting,setSubmitting]=useState(false); const {token,user}=useAuth(); const [form,setForm]=useState({service:initial,practitioner:'',preferred_date:'',preferred_time:'',patient_name:user?.name||'',phone:'',notes:''}); useEffect(()=>{if(user?.name&&!form.patient_name)setForm(current=>({...current,patient_name:user.name}))},[user?.name,form.patient_name]); const update=(key:string,value:string)=>setForm(current=>({...current,[key]:value})); const next=()=>{setError(''); if(step===1&&!form.service)return setError('Choose a service to continue.'); if(step===3&&(!form.preferred_date||!form.preferred_time))return setError('Choose a preferred date and time.'); if(step===4&&(!form.patient_name.trim()||!form.phone.trim()))return setError('Add your name and phone number.'); setStep(Math.min(5,step+1))}; const submit=async()=>{if(!token){setError('Please sign in before submitting your appointment request. Your form is still here, so you can sign in and return.');return} setSubmitting(true); setError(''); try { const r=await fetch(`${API}/appointments`,{method:'POST',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify(form)}); const d=await r.json().catch(()=>({})); if(!r.ok){setError(typeof d.detail==='string'?d.detail:'Could not submit request.');return} setDone(true) } catch { setError('The secure server is unavailable. Start the backend and try again.') } finally { setSubmitting(false) }}; if(done)return <section className="section status-page"><div className="status-card"><Check/><span className="eyebrow">Request received</span><h1>Your preference has been recorded.</h1><p>This is a pending request—not a confirmed appointment. No email notification is configured in this local demonstration.</p><Link className="button" to="/my-appointments">View my requests</Link></div></section>; return <><PageHero eyebrow="Appointment request" title="Care, on your terms." copy="Share your service and preferred time in five clear steps. Availability is not invented or guaranteed."/><section className="section booking-section"><div className="shell booking-layout"><ol className="progress">{['Service','Professional','Date & time','Your details','Review'].map((s,i)=><li className={step>=i+1?'active':''} key={s}><span>{step>i+1?<Check/>:i+1}</span>{s}</li>)}</ol><div className="booking-form"><AnimatePresence mode="wait"><motion.div key={step} initial={{opacity:0,x:18}} animate={{opacity:1,x:0}} exit={{opacity:0,x:-18}}><span className="eyebrow">Step {step} of 5</span>{step===1&&<><h2>What can we help with?</h2><div className="choice-grid">{services.map(s=><button className={form.service===s.slug?'selected':''} onClick={()=>update('service',s.slug)} key={s.slug}><HeartPulse/><b>{s.title}</b><small>{s.category}</small></button>)}</div></>}{step===2&&<><h2>Choose a professional</h2><p>Professional availability is not configured. You may leave this open for the care team.</p><div className="choice-grid"><button className={form.practitioner===''?'selected':''} onClick={()=>update('practitioner','')}><UserRound/><b>First available</b><small>Pending team review</small></button>{professionals.map(p=><button className={form.practitioner===p.slug?'selected':''} onClick={()=>update('practitioner',p.slug)} key={p.slug}><UserRound/><b>{p.name}</b><small>{p.specialty}</small></button>)}</div></>}{step===3&&<><h2>Choose your preference</h2><p>No live availability is connected. These fields record your preference only.</p><div className="form-grid"><label>Preferred date<input type="date" min={new Date().toISOString().split('T')[0]} value={form.preferred_date} onChange={e=>update('preferred_date',e.target.value)}/></label><label>Preferred time<input type="time" value={form.preferred_time} onChange={e=>update('preferred_time',e.target.value)}/></label></div></>}{step===4&&<><h2>Tell us about you</h2><div className="form-grid"><label>Full name<input value={form.patient_name} onChange={e=>update('patient_name',e.target.value)} autoComplete="name"/></label><label>Phone number<input value={form.phone} onChange={e=>update('phone',e.target.value)} autoComplete="tel"/></label><label className="wide">Notes<textarea value={form.notes} onChange={e=>update('notes',e.target.value)} rows={4}/></label></div></>}{step===5&&<><h2>Review your request</h2><div className="review"><span>Service<b>{services.find(s=>s.slug===form.service)?.title}</b></span><span>Professional<b>{professionals.find(p=>p.slug===form.practitioner)?.name||'First available'}</b></span><span>Preferred time<b>{form.preferred_date} at {form.preferred_time}</b></span><span>Patient<b>{form.patient_name} · {form.phone}</b></span></div><div className="notice"><ShieldCheck/><span>Submitting creates a pending request. It does not confirm availability or medical care.</span></div></>}</motion.div></AnimatePresence>{error&&<p className="form-error" role="alert">{error}</p>}<div className="step-actions">{step>1&&<button className="button ghost" onClick={()=>setStep(step-1)}><ArrowLeft/> Back</button>}{step<5?<button className="button" onClick={next}>Continue <ArrowRight/></button>:<button className="button" onClick={submit} disabled={submitting}>{submitting?'Sending securely…':'Submit pending request'}</button>}</div></div></div></section></> }

function AuthLayout({ mode }: { mode: 'sign-in'|'sign-up' }) { const isSignIn=mode==='sign-in'; usePage(isSignIn?'Sign In':'Create Account'); const nav=useNavigate(); const {login,register}=useAuth(); const [show,setShow]=useState(false); const [loading,setLoading]=useState(false); const [error,setError]=useState(''); const [fields,setFields]=useState({name:'',email:'',phone:'',password:'',confirm:'',terms:false}); const strength=Math.min(4,[fields.password.length>=8,/[A-Z]/.test(fields.password),/[0-9]/.test(fields.password),/[^A-Za-z0-9]/.test(fields.password)].filter(Boolean).length); const submit=async(e:FormEvent)=>{e.preventDefault();setError(''); if(!isSignIn&&fields.password!==fields.confirm)return setError('Passwords do not match.'); if(!isSignIn&&!fields.terms)return setError('Please accept the terms to continue.'); setLoading(true);try{if(isSignIn)await login(fields.email,fields.password);else await register(fields);nav('/dashboard')}catch(err){setError(err instanceof Error?err.message:'Unable to continue')}finally{setLoading(false)}}; return <section className="auth-page"><div className="auth-photo"><img src={isSignIn?images.authSignin:images.authSignup} alt={isSignIn?'Young doctor and nurse collaborating in a modern clinic':'Young female doctor in a modern clinic'}/><div><Logo/><h1>{isSignIn?'Welcome back to care that knows you.':'Your care journey, in one secure place.'}</h1><p>Persistent account authentication powered by FastAPI and SQLite.</p></div></div><div className="auth-panel"><form onSubmit={submit}><span className="eyebrow">Patient portal</span><h1>{isSignIn?'Welcome back':'Create your account'}</h1><p>{isSignIn?'Sign in to view your local demonstration dashboard.':'Create a persistent patient account to enter the website.'}</p>{!isSignIn&&<><label>Full name<input required autoComplete="name" value={fields.name} onChange={e=>setFields({...fields,name:e.target.value})}/></label><label>Phone number<input required autoComplete="tel" value={fields.phone} onChange={e=>setFields({...fields,phone:e.target.value})}/></label></>}<label>Email address<input type="email" required autoComplete="email" value={fields.email} onChange={e=>setFields({...fields,email:e.target.value})}/></label><label>Password<div className="password"><input type={show?'text':'password'} required minLength={8} autoComplete={isSignIn?'current-password':'new-password'} value={fields.password} onChange={e=>setFields({...fields,password:e.target.value})}/><button type="button" onClick={()=>setShow(!show)} aria-label={show?'Hide password':'Show password'}>{show?<EyeOff/>:<Eye/>}</button></div></label>{!isSignIn&&<><div className="strength" aria-label={`Password strength ${strength} of 4`}>{[1,2,3,4].map(i=><i className={strength>=i?'active':''} key={i}/>)}</div><label>Confirm password<input type="password" required autoComplete="new-password" value={fields.confirm} onChange={e=>setFields({...fields,confirm:e.target.value})}/></label><label className="check"><input type="checkbox" checked={fields.terms} onChange={e=>setFields({...fields,terms:e.target.checked})}/> I agree to the <Link to="/terms">terms</Link> and <Link to="/privacy-policy">privacy policy</Link>.</label></>}{isSignIn&&<div className="form-meta"><label className="check"><input type="checkbox"/> Remember this device</label><Link to="/forgot-password">Forgot password?</Link></div>}{error&&<p className="form-error" role="alert">{error}</p>}<button className="button full" disabled={loading}>{loading?'Please wait…':isSignIn?'Sign in securely':'Create account'}</button><p className="switch-auth">{isSignIn?'New to Healer? ':'Already have an account? '}<Link to={isSignIn?'/sign-up':'/sign-in'}>{isSignIn?'Create account':'Sign in'}</Link></p><div className="demo-note"><LockKeyhole/><span>Your password is securely hashed and your account is stored in the local SQLite database. Email verification is not configured.</span></div></form></div></section> }

function PasswordPage({reset=false}:{reset?:boolean}) { usePage(reset?'Reset Password':'Forgot Password'); const [params]=useSearchParams(); const [sent,setSent]=useState(false); const [email,setEmail]=useState(''); const [token,setToken]=useState(params.get('token')||''); const [password,setPassword]=useState(''); const [error,setError]=useState(''); const submit=async(e:FormEvent)=>{e.preventDefault();setError('');try{const path=reset?'/auth/password-reset/confirm':'/auth/password-reset/request';const body=reset?{token,password}:{email};const r=await fetch(`${API}${path}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Unable to continue.');setSent(true)}catch(e){setError(e instanceof Error?e.message:'Unable to continue.')}};return <section className="simple-form-page"><form onSubmit={submit}><Logo/><span className="eyebrow">Account recovery</span><h1>{reset?'Choose a new password':'Reset your password'}</h1><p>{sent?(reset?'Password reset completed. You can sign in again.':'If the account exists, recovery instructions have been queued. Check your configured email inbox.'):(reset?'Use the secure token from your recovery email.':'Enter your email to request a secure recovery link.')}</p>{!sent&&!reset&&<label>Email address<input type="email" required value={email} onChange={e=>setEmail(e.target.value)}/></label>}{!sent&&reset&&<><label>Recovery token<input required value={token} onChange={e=>setToken(e.target.value)}/></label><label>New password<input type="password" minLength={10} required value={password} onChange={e=>setPassword(e.target.value)}/></label></>}{error&&<p className="form-error">{error}</p>}{!sent&&<button className="button full">{reset?'Update password':'Continue'}</button>}<Link to="/sign-in"><ArrowLeft/> Back to sign in</Link></form></section> }

function Protected({children,fallback='/sign-in'}:{children:ReactNode;fallback?:string}) { const {user,initializing}=useAuth(); if(initializing)return <section className="status-page"><div className="status-card"><ShieldCheck/><p>Verifying your secure session…</p></div></section>; return user?<>{children}</>:<Navigate to={fallback} replace/> }
function DashboardShell({children}:{children:ReactNode}) { const {user,logout}=useAuth(); const staff=user && ['HospitalAdmin','Doctor','Nurse'].includes(user.role); const security=user && ['HospitalAdmin','SecurityAuditor'].includes(user.role); const admin=user?.role==='HospitalAdmin'; return <section className="dashboard"><aside><Logo compact/><nav><NavLink to="/dashboard"><Activity/> Overview</NavLink>{staff&&<NavLink to="/staff/appointments"><CalendarDays/> Care queue</NavLink>}{security&&<NavLink to="/staff/security"><ShieldCheck/> Sentinel</NavLink>}{admin&&<NavLink to="/staff/users"><CircleUserRound/> User management</NavLink>}<NavLink to="/records"><LockKeyhole/> Encrypted records</NavLink><NavLink to="/audit"><ShieldCheck/> Access history</NavLink><NavLink to="/notifications"><Bell/> Notifications</NavLink><NavLink to="/my-appointments"><CalendarDays/> My appointments</NavLink><NavLink to="/profile"><CircleUserRound/> Profile settings</NavLink><NavLink to="/"><Hospital/> Visit website</NavLink></nav><button onClick={logout}><LogOut/> Sign out</button></aside><main><div className="dash-top"><div><span>{user?.role === 'Patient' ? 'Patient' : 'Practitioner'} portal</span><b>{user?.name}</b></div><ShieldCheck/></div>{children}</main></section> }
function RecordVault() { usePage('Encrypted Records'); const {user,token}=useAuth(); return <DashboardShell>{user && token && <Records token={token} email={user.email} role={user.role}/>}</DashboardShell> }
function Dashboard() { usePage('Patient Dashboard'); const {user}=useAuth(); const firstName=user?.name?.split(' ')[0]||'Patient'; return <DashboardShell><motion.section className="dash-welcome dash-welcome-rich" initial={{opacity:0,y:18}} animate={{opacity:1,y:0}} transition={{duration:.55}}><div className="dash-welcome-copy"><span className="eyebrow light">Welcome back, {firstName}</span><h1>Your care, all in one calm place.</h1><p>Manage appointment requests, review account security, and explore connected-care services from your private patient space.</p><div className="dash-welcome-actions"><Link className="button light" to="/appointments">Request an appointment <ArrowRight/></Link><Link className="dash-text-link" to="/my-appointments">View my requests</Link></div></div><div className="dash-welcome-visual"><img src={images.hero} alt="Dr. Amelia Brooks consulting with patients"/><motion.span animate={{y:[0,-6,0]}} transition={{duration:4,repeat:Infinity}}><HeartPulse/> Human care, securely connected</motion.span></div></motion.section><div className="dash-section-title"><div><span className="eyebrow">Your portal</span><h2>What would you like to do?</h2></div><span className="dash-live"><i/> Secure session active</span></div><div className="dash-cards dash-cards-rich">{[
  {icon:<CalendarDays/>,label:'Appointments',title:'View pending requests',copy:'Review your submitted appointment preferences.',to:'/my-appointments',action:'Open appointments',tone:'blue'},
  {icon:<ShieldCheck/>,label:'Privacy',title:'Session protected',copy:'Your password is never stored in browser storage.',to:'/profile',action:'Review account',tone:'green'},
  {icon:<HeartPulse/>,label:'Connected care',title:'Live platform',copy:'Explore the local IoMT monitoring demonstration.',to:'/security',action:'View telemetry',tone:'coral'},
  {icon:<Hospital/>,label:'Healer website',title:'Explore care services',copy:'Return to services, professionals, and facilities.',to:'/',action:'Visit website',tone:'violet'}
].map((card,i)=><motion.article className={`dash-action-card ${card.tone}`} key={card.label} initial={{opacity:0,y:20}} animate={{opacity:1,y:0}} transition={{delay:.12+i*.08}} whileHover={{y:-7}}><div className="dash-card-icon">{card.icon}</div><span>{card.label}</span><h2>{card.title}</h2><p>{card.copy}</p><Link to={card.to}>{card.action} <ArrowRight/></Link></motion.article>)}</div><div className="dash-lower-grid"><motion.article className="dash-care-feature" initial={{opacity:0,x:-18}} animate={{opacity:1,x:0}} transition={{delay:.35}}><img src={images.remoteMonitoring} alt="Nurse helping a patient with a remote heart monitor"/><div><span className="eyebrow">Connected care</span><h2>Technology with a human touch.</h2><p>See how remote monitoring can support a clearer conversation between patients and care teams.</p><Link className="button" to="/services/remote-patient-monitoring">Explore monitoring <ArrowRight/></Link></div></motion.article><motion.aside className="dash-panel dash-account-card" initial={{opacity:0,x:18}} animate={{opacity:1,x:0}} transition={{delay:.42}}><div className="dash-avatar">{user?.name?.split(' ').map(n=>n[0]).slice(0,2).join('').toUpperCase()}</div><span className="eyebrow">Account snapshot</span><h2>{user?.name}</h2><p>{user?.email}</p><div className="dash-account-row"><ShieldCheck/><span><b>Patient access</b><small>Authenticated local account</small></span></div><Link to="/profile">View profile settings <ArrowRight/></Link></motion.aside></div></DashboardShell> }
function MyAppointments() { usePage('My Appointments'); const {token}=useAuth(); const [items,setItems]=useState<Appointment[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); useEffect(()=>{setLoading(true); setError(''); fetch(`${API}/appointments/mine`,{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{if(!r.ok)throw new Error('Unable to load your appointment requests.'); return r.json()}).then(setItems).catch(e=>setError(e instanceof Error?e.message:'Unable to load requests.')).finally(()=>setLoading(false))},[token]); return <DashboardShell><div className="dash-title"><span className="eyebrow">Appointments</span><h1>My appointment requests</h1><Link className="button" to="/appointments">New request</Link></div><div className="dash-panel">{loading?<p>Loading requests…</p>:error?<div className="empty"><ShieldCheck/><h2>Could not load requests</h2><p>{error}</p><button className="button ghost" onClick={()=>window.location.reload()}>Try again</button></div>:items.length?items.map(a=><div className="appointment-row" key={a.id}><CalendarDays/><span><b>{services.find(s=>s.slug===a.service)?.title||a.service}</b><small>{a.preferred_date} at {a.preferred_time}</small></span><em>{a.status}</em></div>):<div className="empty"><CalendarDays/><h2>No requests yet</h2><p>When you submit a pending appointment request, it will appear here.</p><Link className="button ghost" to="/appointments">Start a request</Link></div>}</div></DashboardShell> }
function CareQueue() { usePage('Care Queue'); const {token}=useAuth(); const [items,setItems]=useState<Appointment[]>([]); const [loading,setLoading]=useState(true); const [error,setError]=useState(''); const [busy,setBusy]=useState(''); const load=()=>{setLoading(true);fetch(`${API}/appointments/manage`,{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{if(!r.ok)throw new Error('You are not authorized to manage appointments.');return r.json()}).then(setItems).catch(e=>setError(e instanceof Error?e.message:'Unable to load care queue.')).finally(()=>setLoading(false))}; useEffect(load,[token]); const decide=async(id:string,status:'confirmed'|'declined')=>{setBusy(id);setError('');try{const r=await fetch(`${API}/appointments/${id}`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({status})});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(typeof d.detail==='string'?d.detail:'Unable to update request.')}const updated=await r.json();setItems(current=>current.map(item=>item.id===id?updated:item))}catch(e){setError(e instanceof Error?e.message:'Unable to update request.')}finally{setBusy('')}}; return <DashboardShell><div className="dash-title"><div><span className="eyebrow">Staff workspace</span><h1>Care queue</h1></div><button className="button ghost" onClick={load}>Refresh</button></div><div className="dash-panel">{loading?<p>Loading appointment requests…</p>:error?<div className="empty"><ShieldCheck/><h2>Queue unavailable</h2><p>{error}</p></div>:items.length?items.map(a=><article className="appointment-row" key={a.id}><CalendarDays/><span><b>{services.find(s=>s.slug===a.service)?.title||a.service}</b><small>{a.patient_name} · {a.preferred_date} at {a.preferred_time}</small><small>{a.notes||'No patient note'}</small></span><em>{a.status}</em>{(a.status==='pending review'||a.status==='cancellation requested')&&<span className="queue-actions"><button className="button small" disabled={busy===a.id} onClick={()=>decide(a.id,'confirmed')}>Confirm</button><button className="button small ghost" disabled={busy===a.id} onClick={()=>decide(a.id,'declined')}>Decline</button></span>}</article>):<div className="empty"><CalendarDays/><h2>Queue is clear</h2><p>No appointment requests need attention.</p></div>}</div></DashboardShell> }
function SentinelDashboard() { usePage('Healer Sentinel'); const {token}=useAuth(); const [items,setItems]=useState<Incident[]>([]); const [metrics,setMetrics]=useState<any>(null); const [error,setError]=useState(''); const load=()=>{setError('');Promise.all([fetch(`${API}/security/threat-feed`,{headers:{Authorization:`Bearer ${token}`}}),fetch(`${API}/security/metrics`,{headers:{Authorization:`Bearer ${token}`}})]).then(async([feed,metric])=>{if(!feed.ok)throw new Error('Security console access is restricted.');const f=await feed.json();setItems(f.items||[]);setMetrics(metric.ok?await metric.json():null)}).catch(e=>setError(e instanceof Error?e.message:'Unable to load security data.'))};useEffect(load,[token]);const critical=items.filter(i=>i.severity==='CRITICAL'||i.severity==='HIGH').length;return <DashboardShell><div className="dash-title"><div><span className="eyebrow">Healer Sentinel</span><h1>Security command centre</h1></div><button className="button ghost" onClick={load}>Refresh</button></div>{error?<div className="dash-panel"><div className="empty"><ShieldCheck/><h2>Sentinel unavailable</h2><p>{error}</p></div></div>:<><div className="security-kpis"><article><span>Open incidents</span><b>{critical}</b></article><article><span>Total detected events</span><b>{items.length}</b></article><article><span>Detector mode</span><b>{metrics?.application_event_detection?.evaluation_status||'MODEL'}</b></article></div><div className="dash-panel"><h2>Incident timeline</h2>{items.length?items.map(i=><article className="incident-row" key={i.id}><ShieldCheck/><span><b>{i.attack_type}</b><small>{new Date(i.timestamp).toLocaleString()} · {i.source}{i.is_simulated?' · simulated':''}</small><small>{i.details.reason_codes?.join(' · ')||'No reason codes recorded'}</small></span><em className={i.severity.toLowerCase()}>{i.severity}</em></article>):<div className="empty"><ShieldCheck/><h2>No incidents detected</h2><p>Security events will appear here after server-side evaluation.</p></div>}</div></>}</DashboardShell> }
function UserManagement() { usePage('User Management'); const {token}=useAuth(); const [items,setItems]=useState<User[]>([]); const [error,setError]=useState(''); const [loading,setLoading]=useState(true); const [busy,setBusy]=useState(''); const load=()=>{setLoading(true);fetch(`${API}/auth/users`,{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{if(!r.ok)throw new Error('Administrator access is required.');const d=await r.json();setItems(d.items||[])}).catch(e=>setError(e instanceof Error?e.message:'Unable to load users.')).finally(()=>setLoading(false))};useEffect(load,[token]);const action=async(email:string,path:'approve'|'suspend')=>{setBusy(email);try{const r=await fetch(`${API}/auth/staff/${encodeURIComponent(email)}/${path}`,{method:'POST',headers:{Authorization:`Bearer ${token}`}});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(typeof d.detail==='string'?d.detail:'Unable to update user.')}const updated=await r.json();setItems(current=>current.map(item=>item.email===email?updated:item))}catch(e){setError(e instanceof Error?e.message:'Unable to update user.')}finally{setBusy('')}};return <DashboardShell><div className="dash-title"><div><span className="eyebrow">Administration</span><h1>User management</h1></div><button className="button ghost" onClick={load}>Refresh</button></div><div className="dash-panel">{loading?<p>Loading accounts…</p>:error?<div className="empty"><ShieldCheck/><h2>Users unavailable</h2><p>{error}</p></div>:items.map(item=><article className="user-row" key={item.email}><CircleUserRound/><span><b>{item.name}</b><small>{item.email} · {item.role}</small></span><em>{item.is_active===false?'suspended':item.is_verified?'verified':'pending'}</em>{item.role!=='Patient'&&item.email!==''&&(item.is_verified===false||item.is_active===false)&&<button className="button small" disabled={busy===item.email} onClick={()=>action(item.email,'approve')}>Approve</button>}{item.role!=='Patient'&&item.is_active!==false&&<button className="button small ghost" disabled={busy===item.email} onClick={()=>action(item.email,'suspend')}>Suspend</button>}</article>)}</div></DashboardShell> }
function AuditHistory() { usePage('Access History'); const {token}=useAuth(); const [items,setItems]=useState<AuditItem[]>([]); const [error,setError]=useState(''); const [loading,setLoading]=useState(true); useEffect(()=>{fetch(`${API}/audit/events`,{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{if(!r.ok)throw new Error('Unable to load access history.');const d=await r.json();setItems(d.items||[])}).catch(e=>setError(e instanceof Error?e.message:'Unable to load access history.')).finally(()=>setLoading(false))},[token]);return <DashboardShell><div className="dash-title"><div><span className="eyebrow">Privacy ledger</span><h1>Access history</h1></div></div><div className="notice"><ShieldCheck/><span>This view shows only events you are authorized to see. Medical plaintext and encryption keys are never included.</span></div><div className="dash-panel">{loading?<p>Loading access history…</p>:error?<div className="empty"><ShieldCheck/><h2>History unavailable</h2><p>{error}</p></div>:items.length?items.map(item=><article className="audit-row" key={item.id}><ShieldCheck/><span><b>{item.action.replaceAll('_',' ')}</b><small>{new Date(item.timestamp).toLocaleString()} · {item.resource_type}{item.resource_id?` · ${item.resource_id}`:''}</small></span><em>{item.outcome}</em></article>):<div className="empty"><ShieldCheck/><h2>No events yet</h2><p>Authorized record and account activity will appear here.</p></div>}</div></DashboardShell> }
function NotificationInbox() { usePage('Notifications'); const {token}=useAuth(); const [items,setItems]=useState<NotificationItem[]>([]); const [error,setError]=useState(''); const [loading,setLoading]=useState(true); useEffect(()=>{fetch(`${API}/notifications/mine`,{headers:{Authorization:`Bearer ${token}`}}).then(async r=>{if(!r.ok)throw new Error('Unable to load notifications.');const d=await r.json();setItems(d.items||[])}).catch(e=>setError(e instanceof Error?e.message:'Unable to load notifications.')).finally(()=>setLoading(false))},[token]);return <DashboardShell><div className="dash-title"><div><span className="eyebrow">Care updates</span><h1>Notifications</h1></div></div><div className="notice"><Bell/><span>Appointment and account updates appear here. External email delivery can be connected through the notification worker.</span></div><div className="dash-panel">{loading?<p>Loading notifications…</p>:error?<div className="empty"><Bell/><h2>Notifications unavailable</h2><p>{error}</p></div>:items.length?items.map(item=><article className="notification-row" key={item.id}><Bell/><span><b>{(item.payload.kind||'Notification').replaceAll('_',' ')}</b><small>{new Date(item.created_at).toLocaleString()} · {item.channel}</small>{item.payload.status&&<small>Status: {item.payload.status}</small>}</span><em>{item.status}</em></article>):<div className="empty"><Bell/><h2>No notifications</h2><p>New appointment and security updates will appear here.</p></div>}</div></DashboardShell> }
function Profile() { usePage('Profile Settings'); const {user,token,updateUser}=useAuth(); const [name,setName]=useState(user?.name||''); const [phone,setPhone]=useState(user?.phone||''); const [saving,setSaving]=useState(false); const [message,setMessage]=useState(''); const [error,setError]=useState(''); useEffect(()=>{setName(user?.name||'');setPhone(user?.phone||'')},[user?.name,user?.phone]); const save=async(e:FormEvent)=>{e.preventDefault();setSaving(true);setMessage('');setError('');try{const r=await fetch(`${API}/auth/me`,{method:'PATCH',headers:{'Content-Type':'application/json',Authorization:`Bearer ${token}`},body:JSON.stringify({name,phone:phone||null})});const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(typeof d.detail==='string'?d.detail:'Unable to update profile.');updateUser(d);setMessage('Profile updated successfully.')}catch(e){setError(e instanceof Error?e.message:'Unable to update profile.')}finally{setSaving(false)}};return <DashboardShell><div className="dash-title"><div><span className="eyebrow">Account</span><h1>Profile settings</h1></div></div><form className="dash-panel profile-form" onSubmit={save}><label>Full name<input value={name} onChange={e=>setName(e.target.value)} required minLength={2}/></label><label>Phone number<input value={phone} onChange={e=>setPhone(e.target.value)}/></label><label>Email address<input value={user?.email||''} readOnly/></label><label>Role<input value={user?.role||''} readOnly/></label>{message&&<p className="form-success">{message}</p>}{error&&<p className="form-error">{error}</p>}<div className="notice"><ShieldCheck/><span>Your profile changes are stored securely and recorded in the access history.</span></div><button className="button" disabled={saving}>{saving?'Saving…':'Save profile'}</button></form></DashboardShell> }

function Contact() { usePage('Contact Us'); return <><PageHero eyebrow="Contact" title="Let’s start with a conversation." copy="Reach the HealerPlus demonstration contact desk or send a message through the preview form below." image={images.contactReception}/><section className="section"><div className="shell contact-grid"><div><span className="eyebrow">Demonstration contact</span><h2>We’re here to help.</h2><p>These reserved example details complete the academic interface and should be replaced with verified business information before launch.</p><div className="contact-item"><MapPin/><span><b>HealerPlus Hospital</b>100 Wellness Way, Care District, CA 90001</span></div><div className="contact-item"><Phone/><span><b>Telephone</b><a href="tel:+12025550147">+1 (202) 555-0147</a></span></div><div className="contact-item"><Mail/><span><b>Business email</b><a href="mailto:info@healerplus.example">info@healerplus.example</a></span></div></div><form className="contact-form" onSubmit={e=>e.preventDefault()}><h2>Send a message</h2><p>Message delivery remains disabled until a secure business inbox is connected.</p><label>Name<input/></label><label>Email<input type="email"/></label><label>Message<textarea rows={5}/></label><button className="button" disabled>Messaging not configured</button></form></div></section></> }
function FaqBlock() { const [open,setOpen]=useState(0); return <section className="section sage"><div className="shell faq-layout"><div><span className="eyebrow">Good to know</span><h2>Clear answers, before you begin.</h2><Link to="/faq">View all questions</Link></div><div>{faqs.slice(0,4).map((f,i)=><article className={open===i?'faq open':'faq'} key={f[0]}><button onClick={()=>setOpen(open===i?-1:i)} aria-expanded={open===i}>{f[0]}<ChevronDown/></button>{open===i&&<motion.p initial={{opacity:0,y:-8}} animate={{opacity:1,y:0}}>{f[1]}</motion.p>}</article>)}</div></div></section> }
function FAQ() { usePage('Frequently Asked Questions'); const [open,setOpen]=useState(0); return <><PageHero eyebrow="Help centre" title="Questions deserve clear answers." copy="Important information about the current Healer Mobile Care demonstration."/><section className="section"><div className="shell faq-single">{faqs.map((f,i)=><article className={open===i?'faq open':'faq'} key={f[0]}><button onClick={()=>setOpen(open===i?-1:i)}>{f[0]}<ChevronDown/></button>{open===i&&<p>{f[1]}</p>}</article>)}</div></section></> }
function Legal({type}:{type:'privacy'|'terms'}) { const privacy=type==='privacy'; usePage(privacy?'Privacy Policy':'Terms & Conditions'); return <><PageHero eyebrow="Legal" title={privacy?'Privacy policy':'Terms and conditions'} copy="Plain-language information for this local academic demonstration."/><section className="section"><article className="shell prose"><p><b>Last reviewed: 18 October 2026</b></p><h2>{privacy?'How this demonstration handles information':'Use of this platform'}</h2><p>{privacy?'Authentication is processed by FastAPI and accounts, sessions, appointments and encrypted record envelopes are stored persistently in the configured database. The browser stores a short-lived access token and basic profile in sessionStorage; logout revokes the server session. Passwords are hashed and never stored in browser storage. Do not enter real medical or highly sensitive information.':'This platform is an academic technology demonstration. It is not a healthcare provider, emergency service, diagnostic tool, or guarantee of an appointment. Do not rely on it for clinical decisions.'}</p><h2>Important limitations</h2><p>No production hosting, email provider, verified clinician directory, real-time availability service, deployed blockchain contract, IPFS provider, or regulated patient-record environment is configured. Healthcare imagery is illustrative and does not depict real Healer Mobile Care facilities or verified staff.</p><h2>Security</h2><p>The project demonstrates security concepts, but a production deployment requires an approved identity provider, secure cookie sessions, secrets management, security testing, monitoring, backups, access review and jurisdiction-specific legal review.</p></article></section></> }
function Security() { usePage('Security & Smart Contract Readiness'); const {token}=useAuth(); const [status,setStatus]=useState('Checking…'); const [telemetry,setTelemetry]=useState<any>(null); useEffect(()=>{fetch(`${API}/health`).then(r=>r.json()).then(()=>setStatus('Operational')).catch(()=>setStatus('Offline')); if(token)fetch(`${API}/iomt/stream?mode=normal`,{headers:{Authorization:`Bearer ${token}`}}).then(r=>r.ok?r.json():null).then(setTelemetry).catch(()=>{})},[token]); return <><PageHero eyebrow="Security platform" title="Intelligent defense. Verifiable trust." copy="Local AI analysis and explicitly simulated IoMT telemetry are available. Smart-contract features stay disabled until real contracts and signing infrastructure are configured."/><section className="section dark-section"><div className="shell security-grid"><article><Zap/><span>FastAPI platform</span><h2>{status}</h2><p>Authenticated local backend</p></article><article><HeartPulse/><span>IoMT telemetry</span><h2>{telemetry?.heart_rate_bpm?`${telemetry.heart_rate_bpm} bpm`:'Awaiting signal'}</h2><p>Simulated signal; no clinical device is connected</p></article><article><ShieldCheck/><span>AI intrusion detection</span><h2>Development model</h2><p>40-row demonstration dataset; no production accuracy claim</p></article></div><div className="shell tech-flow"><div>Authenticated account</div><ChevronRight/><div>Encrypted API layer</div><ChevronRight/><div>Local anomaly model</div><ChevronRight/><div>Blockchain not configured</div></div></section></> }
function NotFound(){usePage('Page Not Found');return <section className="status-page"><div className="status-card"><span className="eyebrow">404</span><h1>This page needs a little care.</h1><p>The route you requested does not exist.</p><Link className="button" to="/">Return home</Link></div></section>}

function SiteLayout(){const location=useLocation();return <><Header/><AnimatePresence mode="wait"><motion.main key={location.pathname} initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} transition={{duration:.22}}><Routes><Route path="/" element={<Home/>}/><Route path="/about" element={<About/>}/><Route path="/services" element={<Services/>}/><Route path="/services/:slug" element={<ServiceDetail/>}/><Route path="/doctors" element={<Doctors/>}/><Route path="/doctors/:slug" element={<DoctorProfile/>}/><Route path="/facilities" element={<Facilities/>}/><Route path="/appointments" element={<AppointmentPage/>}/><Route path="/contact" element={<Contact/>}/><Route path="/faq" element={<FAQ/>}/><Route path="/privacy-policy" element={<Legal type="privacy"/>}/><Route path="/terms" element={<Legal type="terms"/>}/><Route path="/security" element={<Security/>}/><Route path="*" element={<NotFound/>}/></Routes></motion.main></AnimatePresence><Footer/></>}
export default function App(){return <AuthProvider><Routes><Route path="/sign-in" element={<AuthLayout mode="sign-in"/>}/><Route path="/sign-up" element={<AuthLayout mode="sign-up"/>}/><Route path="/forgot-password" element={<PasswordPage/>}/><Route path="/reset-password" element={<PasswordPage reset/>}/><Route path="/dashboard" element={<Protected><Dashboard/></Protected>}/><Route path="/records" element={<Protected><RecordVault/></Protected>}/><Route path="/audit" element={<Protected><AuditHistory/></Protected>}/><Route path="/notifications" element={<Protected><NotificationInbox/></Protected>}/><Route path="/my-appointments" element={<Protected><MyAppointments/></Protected>}/><Route path="/staff/appointments" element={<Protected><CareQueue/></Protected>}/><Route path="/staff/security" element={<Protected><SentinelDashboard/></Protected>}/><Route path="/staff/users" element={<Protected><UserManagement/></Protected>}/><Route path="/profile" element={<Protected><Profile/></Protected>}/><Route path="/*" element={<SiteLayout/>}/></Routes></AuthProvider>}
